import{_ as i,o as p,c as e,a0 as l}from"./chunks/framework.tsJrOMu2.js";const c=JSON.parse('{"title":"WireGuard 配置没错，为什么 VPS 收不到 UDP 包？一次家庭内网穿透排障复盘","description":"一次真实的家庭远程访问排障：Windows 客户端已经发出 UDP，VPS 上 WireGuard、UFW 和监听都正常，但 tcpdump 抓包为 0。问题到底在哪里？","frontmatter":{"title":"WireGuard 配置没错，为什么 VPS 收不到 UDP 包？一次家庭内网穿透排障复盘","description":"一次真实的家庭远程访问排障：Windows 客户端已经发出 UDP，VPS 上 WireGuard、UFW 和监听都正常，但 tcpdump 抓包为 0。问题到底在哪里？","date":"2026-05-22T01:20:00.000Z","tags":["WireGuard","VPS","内网穿透","UDP","家庭网络","故障排查"],"categories":["折腾笔记"]},"headers":[],"relativePath":"tinkering/wireguard-vps-udp-no-packet-2026-05-22.md","filePath":"tinkering/wireguard-vps-udp-no-packet-2026-05-22.md"}'),s={name:"tinkering/wireguard-vps-udp-no-packet-2026-05-22.md"};function n(t,a,r,d,o,h){return p(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="wireguard-配置没错-为什么-vps-收不到-udp-包-一次家庭内网穿透排障复盘" tabindex="-1">WireGuard 配置没错，为什么 VPS 收不到 UDP 包？一次家庭内网穿透排障复盘 <a class="header-anchor" href="#wireguard-配置没错-为什么-vps-收不到-udp-包-一次家庭内网穿透排障复盘" aria-label="Permalink to &quot;WireGuard 配置没错，为什么 VPS 收不到 UDP 包？一次家庭内网穿透排障复盘&quot;">​</a></h1><p>折腾家庭远程访问时，最容易让人崩溃的一类问题是：<strong>配置看起来都对，但就是连不上。</strong></p><p>这次遇到的就是一个典型案例：家里的 Windows 主机已经启用了 WireGuard 客户端，VPS 端也配置好了 WireGuard Server，防火墙、监听端口、Peer 信息看起来都没问题，但就是没有握手。</p><p>一开始很容易怀疑：</p><ul><li>WireGuard 配置是不是写错了？</li><li>Endpoint 端口是不是错了？</li><li>Windows 防火墙是不是拦了？</li><li>VPS 的 UFW 是不是没放行？</li><li>要不要干脆重装系统？</li></ul><p>但最后排下来，真正的问题并不在 WireGuard，而是在 <strong>VPS 公网 UDP 入站链路</strong>。</p><p>这篇文章就复盘一下这个排障过程，尤其适合正在搭建 WireGuard、Tailscale 替代方案、家庭内网穿透或者远程访问入口的朋友参考。</p><h2 id="目标-让外部设备通过-vps-回到家里" tabindex="-1">目标：让外部设备通过 VPS 回到家里 <a class="header-anchor" href="#目标-让外部设备通过-vps-回到家里" aria-label="Permalink to &quot;目标：让外部设备通过 VPS 回到家里&quot;">​</a></h2><p>整体目标很简单：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>外部设备 / 手机 / 笔记本</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>      VPS 中转</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>   家庭内网节点</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span> Windows 主机 / NAS / PVE / 旁路由</span></span></code></pre></div><p>这种架构的好处是：</p><ul><li>家里不需要公网 IP；</li><li>不用在家用路由器上暴露端口；</li><li>VPS 可以作为固定入口；</li><li>多台设备都可以接入同一个 WireGuard 网络；</li><li>后续可以扩展到 NAS、PVE、旁路由等更多内网服务。</li></ul><p>理论上很优雅，但实际部署时，第一步就卡住了：<strong>WireGuard 没有握手。</strong></p><h2 id="表面现象-vps-有-peer-但没有握手" tabindex="-1">表面现象：VPS 有 Peer，但没有握手 <a class="header-anchor" href="#表面现象-vps-有-peer-但没有握手" aria-label="Permalink to &quot;表面现象：VPS 有 Peer，但没有握手&quot;">​</a></h2><p>VPS 端 WireGuard 配置完成后，可以看到 Peer 已经存在。也就是说，服务端配置文件并不是完全没加载。</p><p>但关键问题是：</p><ul><li>没有 <code>latest handshake</code>；</li><li>没有 Rx / Tx 流量；</li><li>客户端显示已启用，但服务端没有收到任何有效通信。</li></ul><p>这种状态通常说明：客户端要么没发出去，要么包在路上被拦了，要么 VPS 系统层没有收到。</p><p>排障不能靠猜，要一步一步把链路切开。</p><h2 id="第一步-先确认客户端有没有真的发-udp" tabindex="-1">第一步：先确认客户端有没有真的发 UDP <a class="header-anchor" href="#第一步-先确认客户端有没有真的发-udp" aria-label="Permalink to &quot;第一步：先确认客户端有没有真的发 UDP&quot;">​</a></h2><p>在 Windows 客户端侧，用 PowerShell 做了一次 UDP 发送测试。</p><p>测试结果返回了字节数，说明本机确实向 VPS 的目标端口发出了 UDP 数据。</p><p>这一步很关键，因为它先排除了一个方向：</p><blockquote><p>不是 Windows 完全没有发包。</p></blockquote><p>当然，这并不代表包一定到达 VPS。它只能说明客户端本机网络栈已经尝试发送。</p><h2 id="第二步-检查-vps-本机-wireguard-和防火墙" tabindex="-1">第二步：检查 VPS 本机 WireGuard 和防火墙 <a class="header-anchor" href="#第二步-检查-vps-本机-wireguard-和防火墙" aria-label="Permalink to &quot;第二步：检查 VPS 本机 WireGuard 和防火墙&quot;">​</a></h2><p>接着在 VPS 上检查：</p><ul><li>WireGuard 接口是否存在；</li><li><code>wg show</code> 是否能看到服务端和 Peer；</li><li>UFW 是否放行了目标 UDP 端口；</li><li>系统是否确实在监听对应端口。</li></ul><p>这些检查都没有发现明显问题。</p><p>如果问题在 VPS 系统内部，通常至少能看到 UDP 包打到网卡，然后再被服务、防火墙或路由规则处理掉。</p><p>所以继续看最关键的一步：抓包。</p><h2 id="第三步-用-tcpdump-看包有没有进入-vps-网卡" tabindex="-1">第三步：用 tcpdump 看包有没有进入 VPS 网卡 <a class="header-anchor" href="#第三步-用-tcpdump-看包有没有进入-vps-网卡" aria-label="Permalink to &quot;第三步：用 tcpdump 看包有没有进入 VPS 网卡&quot;">​</a></h2><p>在 VPS 上抓目标 WireGuard 端口：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcpdump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ni</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> any</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> udp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8512</span></span></code></pre></div><p>结果是：<strong>0 包。</strong></p><p>为了避免是端口写错，又扩大范围抓所有 UDP：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcpdump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ni</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> any</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> udp</span></span></code></pre></div><p>结果仍然是：<strong>0 包。</strong></p><p>这个结果非常关键。</p><p>如果 Windows 已经发出 UDP，而 VPS 上 <code>tcpdump</code> 连任何 UDP 包都抓不到，那就说明问题大概率发生在 VPS 系统之外：</p><ul><li>云厂商安全组没有真正放行；</li><li>公网 IP / EIP 还有单独防火墙；</li><li>Cloud Firewall / ACL 拦截了 UDP；</li><li>DDoS 清洗策略默认丢弃某些 UDP；</li><li>防火墙规则没有绑定到当前实例；</li><li>规则保存了，但没有 Apply / Attach / Bind 生效。</li></ul><p>一句话：</p><blockquote><p><strong>包根本没进系统网卡，继续改 WireGuard 配置意义不大。</strong></p></blockquote><h2 id="最容易走错的方向-重装系统" tabindex="-1">最容易走错的方向：重装系统 <a class="header-anchor" href="#最容易走错的方向-重装系统" aria-label="Permalink to &quot;最容易走错的方向：重装系统&quot;">​</a></h2><p>这类问题特别容易诱导人重装系统。</p><p>因为从表面看，VPS 上服务没握手，很多人第一反应就是：</p><ul><li>重装 Ubuntu；</li><li>重新安装 WireGuard；</li><li>换一份配置；</li><li>反复开关 UFW；</li><li>改监听端口。</li></ul><p>但如果 <code>tcpdump -ni any udp</code> 都是 0 包，重装系统通常救不了。</p><p>原因很简单：</p><blockquote><p>操作系统还没看到包，问题就已经发生了。</p></blockquote><p>这时候真正要查的是云平台网络层，而不是 Linux 系统层。</p><h2 id="正确排查清单" tabindex="-1">正确排查清单 <a class="header-anchor" href="#正确排查清单" aria-label="Permalink to &quot;正确排查清单&quot;">​</a></h2><p>遇到类似问题，可以按下面这个顺序查。</p><h3 id="_1-查安全组是否绑定到当前实例" tabindex="-1">1. 查安全组是否绑定到当前实例 <a class="header-anchor" href="#_1-查安全组是否绑定到当前实例" aria-label="Permalink to &quot;1. 查安全组是否绑定到当前实例&quot;">​</a></h3><p>很多 VPS 控制台里，安全组规则和实例绑定是两件事。</p><p>你可能已经创建了 UDP 放行规则，但它没有绑定到真正运行 WireGuard 的那台机器。</p><p>重点确认：</p><ul><li>入站规则是否是 UDP；</li><li>端口是否正确；</li><li>来源是否允许你的客户端 IP，测试阶段可临时用 <code>0.0.0.0/0</code>；</li><li>规则是否绑定当前实例；</li><li>修改后是否需要保存、应用或重新部署。</li></ul><h3 id="_2-查公网-ip-eip-防火墙" tabindex="-1">2. 查公网 IP / EIP 防火墙 <a class="header-anchor" href="#_2-查公网-ip-eip-防火墙" aria-label="Permalink to &quot;2. 查公网 IP / EIP 防火墙&quot;">​</a></h3><p>有些云厂商不仅有实例安全组，还有公网 IP 层面的防火墙。</p><p>这会导致一个很坑的现象：</p><ul><li>实例安全组看起来放行了；</li><li>系统防火墙也放行了；</li><li>但公网 IP 层仍然拦着 UDP。</li></ul><p>所以要单独检查 EIP、防火墙策略、ACL 或 Cloud Firewall 页面。</p><h3 id="_3-换一个常见端口做对照" tabindex="-1">3. 换一个常见端口做对照 <a class="header-anchor" href="#_3-换一个常见端口做对照" aria-label="Permalink to &quot;3. 换一个常见端口做对照&quot;">​</a></h3><p>可以临时新增一条 UDP <code>51820</code> 入站规则，然后抓包：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcpdump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ni</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> any</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> udp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 51820</span></span></code></pre></div><p>再从客户端往这个端口发 UDP。</p><p>如果 51820 也抓不到，基本可以判断不是 WireGuard 端口配置问题，而是 UDP 入站整体没进来。</p><p>如果 51820 能抓到、原端口抓不到，那就说明原端口规则没有真正生效，或者被特殊策略拦截。</p><h3 id="_4-确认服务商是否限制-udp" tabindex="-1">4. 确认服务商是否限制 UDP <a class="header-anchor" href="#_4-确认服务商是否限制-udp" aria-label="Permalink to &quot;4. 确认服务商是否限制 UDP&quot;">​</a></h3><p>有些低价 VPS、NAT VPS 或特殊线路机器，对 UDP 支持并不完整。</p><p>它可能不会在商品页面上写得很清楚，但实际网络层会限制、清洗或丢弃 UDP。</p><p>如果你要长期跑 WireGuard，选 VPS 时一定要确认：</p><ul><li>是否支持 UDP 入站；</li><li>是否支持自定义安全组；</li><li>是否有独立防火墙；</li><li>是否允许 WireGuard / VPN 类用途；</li><li>是否有 DDoS 策略影响 UDP。</li></ul><h2 id="如果云厂商-udp-不通-怎么办" tabindex="-1">如果云厂商 UDP 不通，怎么办？ <a class="header-anchor" href="#如果云厂商-udp-不通-怎么办" aria-label="Permalink to &quot;如果云厂商 UDP 不通，怎么办？&quot;">​</a></h2><p>有三条路。</p><h3 id="方案一-换一台-udp-正常的-vps" tabindex="-1">方案一：换一台 UDP 正常的 VPS <a class="header-anchor" href="#方案一-换一台-udp-正常的-vps" aria-label="Permalink to &quot;方案一：换一台 UDP 正常的 VPS&quot;">​</a></h3><p>这是最干净的方案。</p><p>WireGuard 本身就是 UDP 协议，如果 VPS 的 UDP 入站不可靠，后面会一直踩坑。</p><p>适合目标：</p><ul><li>想要完整 VPN；</li><li>想访问整个家庭内网；</li><li>想让手机、笔记本、家里节点都进同一个虚拟网；</li><li>后续还要扩展 PVE、NAS、旁路由管理。</li></ul><p>推荐架构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>手机 / 笔记本</span></span>
<span class="line"><span>      ↓ WireGuard</span></span>
<span class="line"><span>    VPS Hub</span></span>
<span class="line"><span>      ↓ WireGuard</span></span>
<span class="line"><span> 家里常开 Linux 节点 / 旁路由</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span> 家庭内网服务</span></span></code></pre></div><p>注意：家里的 Windows 主机如果会关机，不适合作为长期入口。更合适的入口是常开的 Linux 节点、旁路由、PVE 上的小 VM，或者专门的低功耗设备。</p><h3 id="方案二-改用-tcp-隧道" tabindex="-1">方案二：改用 TCP 隧道 <a class="header-anchor" href="#方案二-改用-tcp-隧道" aria-label="Permalink to &quot;方案二：改用 TCP 隧道&quot;">​</a></h3><p>如果暂时不想换 VPS，可以绕开 UDP，用 TCP 隧道类工具：</p><ul><li>frp；</li><li>rathole；</li><li>gost；</li><li>cloudflared tunnel；</li><li>其他基于 TCP/443 的反向隧道。</li></ul><p>这种方式更像“端口映射”或“反向代理”，不如 WireGuard 那么像完整 VPN，但胜在能绕过 UDP 被拦的问题。</p><p>适合目标：</p><ul><li>只想暴露某几个管理端口；</li><li>只需要远程桌面、SSH、Web 管理页；</li><li>不需要完整访问整个家庭网段。</li></ul><h3 id="方案三-用-tailscale-zerotier-等现成组网工具" tabindex="-1">方案三：用 Tailscale / ZeroTier 等现成组网工具 <a class="header-anchor" href="#方案三-用-tailscale-zerotier-等现成组网工具" aria-label="Permalink to &quot;方案三：用 Tailscale / ZeroTier 等现成组网工具&quot;">​</a></h3><p>如果不想维护太多底层配置，可以考虑 Tailscale 或 ZeroTier。</p><p>它们也会用 UDP，但具备 NAT 穿透和中继能力。即使直连失败，也可能通过中继兜底。</p><p>缺点是依赖第三方控制面或中继网络，不如自建 WireGuard 完全可控。</p><h2 id="这次排障最大的收获" tabindex="-1">这次排障最大的收获 <a class="header-anchor" href="#这次排障最大的收获" aria-label="Permalink to &quot;这次排障最大的收获&quot;">​</a></h2><p>这次真正有价值的不是“某个端口怎么放行”，而是排障思路：</p><blockquote><p><strong>当 WireGuard 没握手时，不要先陷入配置文件。先确认 UDP 包有没有进入 VPS 网卡。</strong></p></blockquote><p>判断顺序可以记成一句话：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端是否发包 → VPS 网卡是否收到 → 系统防火墙是否放行 → WireGuard 是否处理 → 路由是否正确</span></span></code></pre></div><p>其中最有分水岭意义的，就是 <code>tcpdump</code>。</p><p>如果 VPS 能抓到 UDP 包，再去查 WireGuard 配置、密钥、AllowedIPs、路由、防火墙。</p><p>如果 VPS 连包都抓不到，就该去查云厂商网络层、安全组、EIP 防火墙、ACL 或直接换 VPS。</p><h2 id="最后给家庭内网远程访问的建议" tabindex="-1">最后给家庭内网远程访问的建议 <a class="header-anchor" href="#最后给家庭内网远程访问的建议" aria-label="Permalink to &quot;最后给家庭内网远程访问的建议&quot;">​</a></h2><p>如果是家庭实验室、NAS、PVE、旁路由这类场景，我更建议这样设计：</p><ol><li>VPS 只做固定公网入口和中转；</li><li>家里用一台常开节点主动连 VPS；</li><li>不要把会关机的 Windows 主机当唯一入口；</li><li>先打通安全的管理通道，再考虑把整个网段路由进去；</li><li>所有公网入口默认最小开放，只放必要端口。</li></ol><p>家庭网络越折腾，越要记住一点：</p><blockquote><p><strong>远程入口一定要放在稳定、常开、可恢复的节点上。</strong></p></blockquote><p>否则你会遇到一个很尴尬的问题：入口机器一关机，你连修它的路都没了。</p><p>本内容由 AI Agent 自动生成，仅供参考，不代表专业意见。</p>`,109)])])}const P=i(s,[["render",n]]);export{c as __pageData,P as default};
